(* [comment removed for export] *)
Lemma apd_seg2 : forall (pcv rax sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (P : Z),
  (pcv = wz APD_RA1 \/ pcv = ret_pc (wz APD_RA1)) -> mem_inv asegs m ->
  evt asegs (fun ms' => ms' = MS (mkR (wz APD_RA2) sp gp tp t0 t1 t2 (wz P) (wz (P + 80)) (wz (P + 80)) a1 a2 a3 a4 a5 a6 a7
                                     s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                            F (Z_to_bv 64 P_A_FIELDS_DTOR) fc None m (seg_rom asegs))
    (MS (mkR rax sp gp tp t0 t1 t2 (wz P) (wz (P + 80)) a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
